      ".dshFsSplit{flex:1;min-height:0;display:flex;flex-direction:row;min-width:0}",
      ".dshFsTree{flex:0 0 280px;width:280px;overflow:auto;border-right:1px solid var(--dsw-alias-border-l2);background:var(--dsw-alias-bg-layer-1);padding:6px 4px;box-sizing:border-box}",
      ".dshFsRow{display:flex;align-items:center;gap:4px;padding:3px 8px;border-radius:6px;cursor:pointer;white-space:nowrap;font-family:ui-monospace,Menlo,monospace;font-size:12px;color:var(--dsw-alias-label-secondary)}",
